// src/components/MovieSearchBar.js

import React, { useState } from 'react';
import { searchMovies } from '../api/movieApi'; // 기존 API 재사용

function MovieSearchBar({ onMovieSelect }) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);

  const handleSearch = async () => {
    if (!query.trim()) return;
    const movies = await searchMovies(query);
    setResults(movies.slice(0, 5)); // 상위 5개 결과만 표시
  };

  const handleSelect = (movie) => {
    onMovieSelect(movie); // 선택한 영화 정보를 부모로 전달
    setQuery(''); // 검색창 초기화
    setResults([]); // 결과 목록 초기화
  };

  return (
    <div className="movie-search-bar">
      <div className="search-input-group">
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="관람한 영화를 검색하세요"
        />
        <button onClick={handleSearch}>검색</button>
      </div>
      {results.length > 0 && (
        <ul className="search-results-list">
          {results.map((movie) => (
            <li key={movie.movieCd} onClick={() => handleSelect(movie)}>
              {movie.movieNm} ({movie.openDt.substring(0, 4)})
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default MovieSearchBar;
